    ListNode(int x) { data = x; next = null; }
    ListNode(int x, ListNode next) { data = x; this.next = next; }
}
*/

class Solution {
    public ListNode deleteNodeWithValueX(ListNode head, int X) {
        ListNode dummy = new ListNode(0, head);
        ListNode previous = dummy;
        ListNode current = head;

        while (current != null) {
            if (current.data == X) {
                previous.next = current.next;
                break;
            }
            previous = current;
            current = current.next;
        }

        return dummy.next;
    }
}
```

Dry run for `5 -> 8 -> 3` and `X = 8`: `current` reaches `8`, and `previous.next` changes from `8` to `3`. The result is `5 -> 3`.

Time complexity: `O(n)`.
Space complexity: `O(1)`. The original links are updated, and only the first matching node is removed.

